parsed = json.loads(text)\\n    print(f\\\"  parsed JSON: {parsed!r}\\\")\\n    print(f\\\"  parsed[0] dict identity/length: len={len(parsed[0])}, keys={list(parsed[0])!r}\\\")\\n    print()\\n    return {\\n        \\\"label\\\": label,\\n        \\\"columns\\\": raw_cols,\\n        \\\"rows\\\": raw_rows,\\n        \\\"message\\\": msg,\\n        \\\"json_text\\\": text,\\n        \\\"parsed\\\": parsed,\\n    }\\n\\n\\nprint(f\\\"[{ 'CASE A' }] duplicate column name 'id' — original query, no renaming\\\")\\ncase_a = probe(\\\"SELECT 1 AS id, 2 AS id\\\", \\\"/mnt/user-data/outputs/dup-id.json\\\", \\\"CASE A: SELECT 1 AS id, 2 AS id\\\")\\n\\nprint(f\\\"[{ 'CASE B' }] distinct column names 'first_id', 'second_id'\\\")\\ncase_b = probe(\\n    \\\"SELECT 1 AS first_id, 2 AS second_id\\\",\\n    \\\"/mnt/user-data/outputs/distinct-ids.json\\\",\\n    \\\"CASE B: SELECT 1 AS first_id, 2 AS second_id\\\",\\n)\\n\\ncon.close()\\n\\n# ---- Verdicts ----\\ndef check(case, expected):\\n    got = case[\\\"parsed\\\"]\\n    print(f\\\"{case['label']}\\\")\\n    print(f\\\"  source values: {expected}\\\")\\n    print(f\\\"  exported records: {got}\\\")\\n    return got\\n\\nprint(\\\"=\\\" * 70)\\nprint(\\\"VERDICTS\\\")\\nprint(\\\"=\\\" * 70)\\n\\na = check(case_a, [1, 2])\\nprint(f\\\"  CASE A exported records: {len(a)}\\\")\\nprint(f\\\"  CASE A dict keys: {list(a[0])}\\\")\\nprint(f\\\"  CASE A first value survives: {1 in a[0].values()} -> {a[0]}\\\")\\nprint(f\\\"  CASE A both values survive: {sorted(a[0].values()) == [1, 2]}\\\")\\nprint()\\n\\nb = check(case_b, [1, 2])\\nprint(f\\\"  CASE B exported records: {len(b)}\\\")\\nprint(f\\\"  CASE B dict keys: {list(b[0])}\\\")\\nprint(f\\\"  CASE B both values survive: {sorted(b[0].values()) == [1, 2]}\\\")\\n\"}"}}]},"finish_reason":null,"native_finish_reason":null}]}

